example.code:
app.UseHayatePrometheusExporter();   // exposes GET /hayateop/metrics
// or with a custom path:
app.UseHayatePrometheusExporter("/metrics");

services.AddHayateOpenTelemetryMetrics();
// or with configuration:
services.AddHayateOpenTelemetryMetrics(o => o.MeterName = "MyApp.Pools");

services.AddHayatePrometheusExporter();
// or with a custom namespace prefix:
services.AddHayatePrometheusExporter(o => o.Namespace = "myapp");
